        var chatClient = new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(chatEndpoint),
            new Azure.Identity.DefaultAzureCredential())
            .GetChatClient(chatModelId)
            .AsIChatClient();

        s_reportingConfiguration = DiskBasedReportingConfiguration.Create(
            storageRootPath: Path.Combine(context.TestRunResultsDirectory!, "evaluation-reports"),
            evaluators:
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
                new FluencyEvaluator(),
                new GroundednessEvaluator(),
                new RelevanceTruthAndCompletenessEvaluator(),
            ],
            chatConfiguration: new ChatConfiguration(chatClient));
    }

    [AssemblyCleanup]
    public static void Cleanup()
    {
        (s_reportingConfiguration as IDisposable)?.Dispose();
    }

    [TestMethod]
    public async Task Chat_response_is_safe()
    {
        await using var scenario =
            await s_reportingConfiguration!.CreateScenarioRunAsync(
                scenarioName: nameof(Chat_response_is_safe));

