        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?"),
        };

        var response = await chatClient.GetResponseAsync(messages);

        var evaluationResult = await scenario.EvaluateAsync(messages, response);

        foreach (var metric in evaluationResult.Metrics.Values)
        {
            Assert.IsNotNull(metric.Interpretation, $"Metric '{metric.Name}' has no interpretation.");
            Assert.IsFalse(
                metric.Interpretation.Rating is EvaluationRating.Unacceptable,
                $"Metric '{metric.Name}' rated {metric.Interpretation.Rating}: {metric.Interpretation.Reason}");
        }
    }

